# frozen_string_literal: true

module Security
  module SecretDetection
    module PartnerTokens
      # Auto-generated by ClientGenerator from a reviewed VendorDefinition.
      # Vendor docs: https://docs.segmentapis.com/tag/Testing#operation/echo
      # Regenerate rather than hand-editing; keep the VendorDefinition as the source of truth.
      class SegmentClient < BaseClient
        # Separate regional stacks: a live token gets the dead code on every host but its own.
        API_ENDPOINTS = [
          "https://api.segmentapis.com/echo?message=ok",
          "https://eu1.api.segmentapis.com/echo?message=ok"
        ].freeze

        private

        def partner_name
          "segment"
        end

        def verify_partner_token(token_value)
          API_ENDPOINTS.each do |endpoint|
            response = make_request(
              endpoint,
              method: :get,
              headers: { 'Authorization' => "Bearer #{token_value}", 'Accept' => 'application/json' }
            )
            result = analyze_response(response)
            return result if result
          end

          token_response(:inactive)
        end

        # nil means this host does not know the token, so the next host decides.
        def analyze_response(response)
          case response.code.to_i
          when 200
            token_response(:active)
          when 403
            nil
          when 429
            raise RateLimitError, "segment rate limited: #{response.code}"
          when 500, 502, 503, 504
            raise NetworkError, "segment service error: #{response.code}"
          else
            # unknown-never-inactive: unmapped codes are never treated as dead tokens.
            token_response(:unknown)
          end
        end
      end
    end
  end
end
